// Shared ember pixel-flame builder for the store-asset templates.
const FLAME = [
  "00011000",
  "00111100",
  "00111100",
  "01122110",
  "01122110",
  "11222211",
  "01122110",
  "00111100",
];
const STOPS = [
  [0.0, [255, 206, 107]],
  [0.55, [242, 121, 43]],
  [1.0, [207, 74, 31]],
];
function ember(t) {
  for (let i = 1; i < STOPS.length; i++) {
    if (t <= STOPS[i][0]) {
      const [t0, c0] = STOPS[i - 1];
      const [t1, c1] = STOPS[i];
      const k = (t - t0) / (t1 - t0);
      return c0.map((v, j) => Math.round(v + (c1[j] - v) * k));
    }
  }
  return STOPS[STOPS.length - 1][1];
}
function buildFlame(el, cell, gap) {
  el.style.display = "inline-grid";
  el.style.gridTemplateColumns = `repeat(8, ${cell}px)`;
  el.style.gap = `${gap}px`;
  el.style.lineHeight = "0";
  FLAME.forEach((row, r) => {
    row.split("").forEach((ch) => {
      const s = document.createElement("span");
      s.style.width = cell + "px";
      s.style.height = cell + "px";
      s.style.borderRadius = Math.max(0.5, cell * 0.12) + "px";
      if (ch !== "0") {
        const lift = ch === "2" ? 28 : 0;
        const [R, G, B] = ember(r / (FLAME.length - 1));
        s.style.background = `rgb(${Math.min(255, R + lift)},${Math.min(
          255,
          G + lift
        )},${Math.min(255, B + lift)})`;
      } else {
        s.style.background = "transparent";
      }
      el.appendChild(s);
    });
  });
}

import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";
import vm from "node:vm";

test("background lifecycle and storage changes keep toolbar badge truthful", async () => {
  const listeners = {};
  const calls = [];
  let enabled = true;
  const chrome = {
    action: {
      setBadgeText(value) {
        calls.push(["text", JSON.parse(JSON.stringify(value))]);
      },
      setBadgeBackgroundColor(value) {
        calls.push(["color", JSON.parse(JSON.stringify(value))]);
      },
    },
    runtime: {
      onInstalled: { addListener(fn) { listeners.installed = fn; } },
      onStartup: { addListener(fn) { listeners.startup = fn; } },
    },
    storage: {
      sync: {
        get(defaults, callback) {
          assert.equal(defaults.enabled, true);
          assert.deepEqual(Object.keys(defaults), ["enabled"]);
          callback({ enabled });
        },
      },
      onChanged: { addListener(fn) { listeners.changed = fn; } },
    },
  };
  const source = await readFile(new URL("../src/background.js", import.meta.url), "utf8");
  vm.runInNewContext(source, { chrome }, { filename: "public/extension/src/background.js" });

  listeners.installed();
  assert.deepEqual(calls.splice(0), [
    ["text", { text: "ON" }],
    ["color", { color: "#C75B39" }],
  ]);

  enabled = false;
  listeners.startup();
  assert.deepEqual(calls.splice(0), [
    ["text", { text: "" }],
    ["color", { color: "#C75B39" }],
  ]);

  listeners.changed({ enabled: { oldValue: false, newValue: true } }, "sync");
  assert.deepEqual(calls.splice(0), [
    ["text", { text: "ON" }],
    ["color", { color: "#C75B39" }],
  ]);

  listeners.changed({ enabled: { oldValue: true, newValue: false } }, "local");
  listeners.changed({ level: { oldValue: "full", newValue: "lite" } }, "sync");
  assert.deepEqual(calls, []);
});

